// Engine feedback hints per error code (deterministic; no model writes these). Shared by the feedback packets and the auto runner.
export const HINTS=[
  // construction ops: DIVISION_POINT, CENTROID, POINT_REFLECTION, LINE_REFLECTION, PERPENDICULAR_THROUGH, TRANSLATE_POINT, TRANSLATE_LINE
  [/INVALID_DIVISION_RATIO|EXTERNAL_DIVISION_EQUAL_RATIO|INVALID_DIVISION_MODE|DEGENERATE_DIVISION_SEGMENT/,'DIVISION_POINT: inputs [A,B] (two different POINT), args {m,n,mode} with m and n positive typedScalars and mode INTERNAL or EXTERNAL; P divides A->B with AP:PB=m:n. EXTERNAL needs m different from n (m>n puts P beyond B, m<n beyond A). A ratio with a letter, a negative ratio or "a point that divides AB" without numbers cannot be drawn: answer UNSUPPORTED.'],
  [/INVALID_LINE_LABEL/,'lineLabels apply only to a displayed SOURCE_LINE node (the equation given by the problem). A line made by PERPENDICULAR_THROUGH or TRANSLATE_LINE cannot carry an equation label: remove its lineLabels entry and mark the line with a point on it (coordinateLabels), the equation stays in the solution text.'],
  [/DEGENERATE_TRIANGLE/,'CENTROID inputs are three non-collinear POINT nodes (the vertices); collinear points have no centroid triangle.'],
  [/REFLECTION_POINT_AT_CENTER|REFLECTION_POINT_ON_LINE/,'POINT_REFLECTION inputs [P, centre] (centre must differ from P; the origin is a NORMALIZATION_ORIGIN node), LINE_REFLECTION inputs [P, LINE] (P must not lie on the line: the image would coincide with P). Show the image point only when it is a different point.'],
  [/ZERO_TRANSLATION|UNSUPPORTED_SCALAR_REF/,'TRANSLATE_POINT / TRANSLATE_LINE take literal args {dx,dy} (typedScalars, not both 0) and one input (POINT or LINE). A translation given by a vector AB or by letters (a,b) is not supported: use the numbers from the stored solution, or answer UNSUPPORTED.'],
  [/UNSUPPORTED_NODE_ARGS/,'Args per op: DIVISION_POINT {m,n,mode}, TRANSLATE_POINT/TRANSLATE_LINE {dx,dy}, CENTROID / POINT_REFLECTION / LINE_REFLECTION / PERPENDICULAR_THROUGH {} (empty).'],
  [/PIECEWISE_POLY_SLANTED_LINE_|PIECEWISE_POLY_REFERENCE_LINE_INVALID|PIECEWISE_POLY_REFERENCE_LINE_CONTAINS_A_PIECE/,'A slanted line next to a piecewise graph is referenceLines:[{id,slope,intercept,intersectionX}] with slope (not 0) and intercept exact integer, fraction or p+q*sqrt(r) strings (no decimals); a horizontal line is {id,y,intersectionX}, never both. intersectionX lists EVERY intersection with the whole curve (surds like (3+sqrt(34)/2)/2 are fine). A line with a letter in it (y=mx+12, y=x+k, y=p(x-3)+3) is drawn at ONE sample value strictly inside the answer range or at the boundary case the solution discusses; name that value in the caption. labelIntersections is not available on a slanted line: list a rational intersection in requiredPoints with exactCoordinates instead. A line equal to a whole piece or a vertical line: answer UNSUPPORTED.'],
  [/PIECEWISE_POLY_IRRATIONAL_|PIECEWISE_POLY_FORMULA_IRRATIONAL_UNSUPPORTED/,'An irrational coefficient is allowed only as an exact string p+q*sqrt(r) (p,q integers or fractions, r a positive integer), for example "-3+2*sqrt(3)", "3/2-sqrt(3)", "sqrt(7)/2", in pieces[].coefficients, breakpoints, referenceLines y/slope/intercept and the x/y of requiredPoints; a plain quadratic is ONE piece (no breakpoints). ONE radical sqrt(r) for the whole plan (IRRATIONAL_RADICANDS_MIXED: sqrt(2) and sqrt(3) together are refused); nested radicals (sqrt(2+sqrt(3))), two radicals in one coefficient (sqrt(2)+sqrt(3)) and cube roots are IRRATIONAL_FORM_UNSUPPORTED: simplify to one radical or answer UNSUPPORTED. An irrational piece cannot have a display formula (FORMULA_IRRATIONAL_UNSUPPORTED): leave formula out and name the case in the caption. A key point with irrational coordinates is {id,x:"3/2-sqrt(3)",y:"-1/4+3*sqrt(3)"} (exact strings; the engine checks it lies on the curve). Two cases k=-3+2*sqrt(3) and k=-3-2*sqrt(3) are two separate figures (composite-panels-v1 cannot hold irrational coefficients).'],
  [/PIECEWISE_POLY_/,'The engine recomputed the piecewise function exactly from pieces and breakpoints and the claim named in engineResult is false. Recompute it from the pieces: the common value at each breakpoint, every corner and every vertex strictly inside its piece as a requiredPoint, every intersection of each y=c with the whole curve (each piece solved on its own interval, a touching point once, an open end excluded), and a formula that equals the pieces.'],
  [/UNSUPPORTED_GRAPH_SCHEMA/,'mathPlan may contain only schemaVersion, nodes, realization and conditionAudits. displayPoints, displayLines, displayCircles, displaySegments, coordinateLabels, scalarLabels and the like are top-level plan fields.'],
  [/UNSUPPORTED_INTERSECTION_TYPES/,'INTERSECTION inputs must be [line, circle] with the line first, [circle, circle] or [line, line].'],
  [/TANGENT_POINT_NOT_ON_CIRCLE|CONDITION_AUDIT_FAIL/,'The engine checked your construction exactly and the stated condition is false. Recompute the coordinates and conditions from the stored solution.'],
  [/UNSUPPORTED_OVERVIEW_DEGREE/,'The graph engine draws only quadratic polynomials. Draw a straight line with construction-spike-v1 (LINE_THROUGH) instead, or answer UNSUPPORTED if a curve of another degree is essential.'],
  [/RESTRICTED_SOURCE_DOMAIN_NEEDS_CONTEXT_VIEW/,'A restricted domain is not supported yet. If the function is defined on all reals use sourceDomain {kind:ALL_REALS}; if the restriction is essential to the solution, answer UNSUPPORTED.'],
  [/UNSUPPORTED_SCALAR_LABEL_PREFIX/,'A scalar label prefix is "" or one or two Latin letters, optionally followed by ^2 or ^3 (AB, r, S^2).'],
  [/REQUIRED_SOURCE_GEOMETRY_NOT_DISPLAYED/,'Each display list must include every SOURCE_POINT and every GIVEN/CONCLUSION node of its type.'],
  [/LAYOUT_INVENTORY_INCOMPLETE/,'Some labels found no free room on the figure (listed in engineResult). Show fewer labels: coordinate labels only for the decisive points, axisTickValues {x:[],y:[]} when the key points carry coordinate labels, and no optional names or lengths.'],
  [/UNVERIFIED_SEMANTIC_MARK/,'The mark named in engineResult (right angle, tangency, length or angle label) does not hold in the constructed geometry. Fix its refs (for a right angle the vertex is the middle ref) or its value, or remove the mark.'],
  [/INVALID_LABEL_DIRECTIONS/,'labelDirections may name only a point that carries a coordinate label at the point (listed in coordinateLabels and not in coordinatePanel). It cannot move a point-name label; remove the entry or give that point a coordinate label.'],
  [/COORDINATE_PANEL_TOO_TALL/,'The figure including its coordinate band or panel must stay within 600 high (a quadratic plot 1099): use a smaller canvas height or fewer panel lines.'],
  [/OUTPUT_TYPE_MISMATCH/,'A node outputType must match its op: NORMALIZATION_ORIGIN and NORMALIZATION_AXIS are POINT (the axis node is the point (length,0), not a scalar), SOURCE_LINE LINE, SEGMENT_LENGTH SCALAR.'],
  [/NAME_NOT_IN_SOLUTION/,'A displayed point is written with its node id, so the ids listed must be names the stored problem/solution uses. Rename those nodes to the names the solution uses (O for the origin, A, B, M, P ...), or, for helper points the solution does not name, make them DERIVED_INTERMEDIATE and list them in hiddenPointNames, or leave them out of displayPoints. Rename every reference consistently.'],
  [/INEQUALITY_SOLUTION_NOT_ONE_INTERVAL/,'The engine solved the inequality and its set has two pieces (for example x<1 or x>3). The number line draws one interval only: if the solution restricts the variable (a+3>0, x>=-2, t>0), give that condition as inequality.domain so one piece remains; otherwise answer UNSUPPORTED.'],
  [/INEQUALITY_SOLUTION_EMPTY/,'The engine solved the inequality and found no solution in the domain. Check the coefficients (constant, linear, squared, of f in f(variable) comparator 0), the comparator and the domain against the stored solution; an empty set has no number line.'],
  [/INEQUALITY_ADJOINED_POINT_(NOT_ADJACENT|OUTSIDE_DOMAIN|INVALID)/,'Each adjoinedPoints value must be an exact integer or fraction string inside the domain that closes an open end of the solved set (for example "-3" for -3<a<5 when a=-3 is checked separately). Remove a value that the set already contains or that lies apart from it.'],
  [/INEQUALITY_INTEGER_POINTS_(NEED_RANGE|INVALID)|INEQUALITY_TOO_MANY_INTEGER_POINTS/,'integerPoints:true needs a bounded set; for a ray give integerPoints:{range:["lo","hi"]} with integer strings covering the integers the solution counts. At most 25 integer points are drawn.'],
  [/INEQUALITY_NOT_QUADRATIC|INVALID_INEQUALITY_(COEFFICIENT|COMPARATOR)|INEQUALITY_(PLAN|DOMAIN)_INVALID|CHAIN_PLAN_INVALID/,'inequality is {coefficients:[constant, linear, squared] exact integer/fraction strings with a nonzero squared coefficient, comparator "<"|"<="|">"|">=", variable (one lowercase letter, not y), domain {kind:"INTERVAL",range:[lo|null,hi|null],states}, adjoinedPoints, integerPoints}; nothing else. A linear inequality is not supported.'],
  [/CHAIN_CAPTION_INVALID|MISSING_KOREAN_GLYPH/,'A caption is {math?,text?}: math plain ASCII (letters, digits, = + - < > . , parentheses; no / or TeX), text at most 24 characters of ordinary Korean and ASCII (no subscript characters such as ₂).'],
  [/NUMBER_LINE_(LABELS_TOO_CLOSE|INTEGER_POINTS_TOO_DENSE|LABEL_TOO_LARGE)/,'The number-line labels did not fit (ends too close together, or too many integer points for their labels). Narrow integerPoints to the integers the solution needs, or drop integerPoints.'],
  [/RENDERED_LAYOUT_FAIL/,'Labels or marks collide in the rendered figure. Show fewer labels or spread the points.'],
  [/SOURCE_QUOTE_(MISSING|NOT_IN_ITEM)/,'Every plan that draws a figure needs a top-level "sourceQuote": 12 to 40 characters copied exactly from the item.json in THE SAME folder as this plan.json (question or stored solution). If the check says it does not occur in this item, the plan was drawn from another item or the quote was copied from another folder: reopen this folder item.json, re-solve this item, and write the plan and quote from it.'],
  [/REALIZATION_RECIPE_REQUIRED/,'A plan with NORMALIZATION_ORIGIN / NORMALIZATION_AXIS nodes needs mathPlan.realization. For points given in a coordinate plane use {recipeId:"SOURCE_COORDINATE_AXES_v1",unit:"source-coordinate",reflectionEquivalent:false} with one origin and one unit axis of length 1 (see contract.md); otherwise drop the normalization nodes.'],
  // number-line-figure-v1 (standalone number line: rows of solution sets, RESULT intersection, parameter ends, integer points, internal division)
  [/NUMBER_LINE_(RESULT_EMPTY|RESULT_IS_A_POINT|TOO_MANY_PIECES)/,'The engine intersected your SET rows exactly (at the parameter sample value, if any) and the RESULT row is empty, a single point or has more than two pieces. Recompute the intersection from the stored solution: pick the parameter sample value of the case the solution discusses (a boundary value often works), or check the ends and open/closed states of the SET rows. A one-point or three-piece result cannot be drawn: give UNSUPPORTED.'],
  [/NUMBER_LINE_PARAMETER_(MISSING|UNUSED|INVALID|COEFFICIENT_ZERO)/,'A param end {param:{mul,add},state} needs numberLine.parameter:{name:"a",value:"exact"} and a parameter that no end uses is refused. name is one lowercase letter other than the variable and y; value is an exact integer or fraction string (the sample value the figure is drawn at); mul is nonzero. An end that does not depend on the parameter is {value,state}.'],
  [/NUMBER_LINE_PIECES_(OVERLAP|TOUCH)|NUMBER_LINE_PIECE_(INVALID|IS_A_POINT)/,'A SET row is one or two disjoint pieces [lo,hi] with lo<hi at the sample value; pieces that touch or overlap are one piece, a one-point piece cannot be drawn, and an end is {value|param,state} or null (a ray). For x<-1 or x>2 write two pieces: {lo:null,hi:{value:"-1",state:"OPEN"}} and {lo:{value:"2",state:"OPEN"},hi:null}.'],
  [/NUMBER_LINE_(INTEGER_POINTS_(NEED_RANGE|INVALID)|TOO_MANY_INTEGER_POINTS)/,'integerPoints:true needs a bounded row; for a ray or a wide set give integerPoints:{range:["lo","hi"]} (integer strings) covering the integers the solution counts; at most 25 integer dots.'],
  [/NUMBER_LINE_(POINTS_COINCIDE|POINTS_INVALID|DIVISION_INVALID)|NUMBER_LINE_RESULT_(NEEDS_TWO_SETS|NOT_LAST)|NUMBER_LINE_(ROWS|VALUE)_INVALID|NUMBER_LINE_FIGURE_PLAN_INVALID/,'number-line-figure-v1: rows is 1 to 4 rows of {kind:"SET",pieces,integerPoints?}, {kind:"RESULT",integerPoints?} (only after at least two SET rows, last, its ends are computed so never given) or {kind:"POINTS",points} (2 to 4 one-capital-letter points {id,value} or {id,divides:{from,to,ratio:["m","n"]}} for an internal division AP:PB=m:n; an external division is not supported). Values are exact integer or fraction strings, never decimals. The only plan keys are capability, numberLine, numberLineCaption, caption, sourceConditions, newVisualInformation.'],
  [/POINT_DISPLAY_NAME_(INVALID|DUPLICATE|MISMATCH|NOT_SHOWN|PANEL_MISSING)|POINT_NAME_TARGET_(UNKNOWN|HIDDEN)/,'pointNames: {"<point id>":"<display name>"} at the top level of the plan (construction plan, graph plan, number-line figure plan or composite panel plan). Keep the id simple (A, B, T1, T2); the display name is ONE capital letter + optional prime (A prime written as a straight quote or the prime sign; two primes allowed) + optional subscript digits 1-9, at most two (T_1, T_{1} or T₁). Anything else (lowercase, words, digit 0, subscript before the prime) is invalid. A key must be a point the figure draws (construction displayPoints / graph requiredPoints / number-line POINTS ids); two points may not show the same name; a hiddenPointNames point cannot be named. A named graph point with coordinates moves to the coordinate band (T₁(x, y)); without coordinates only its name is drawn at the dot. Write the same spelling in the solution text.'],
  [/APPLICATION_AXES_|INVALID_APPLICATION_AXES/,"applicationAxes:true is only for a word problem whose axes measure different quantities (a count against a money amount): a quadratic (polynomial-spike-v1) with sourceDomain {kind:INTERVAL,range:[lo,hi]}, never axisSqueeze or plotCanvas, and graphPlan.axisTickValues {x:[...],y:[...]} with 2 to 8 nonzero values per axis in an arithmetic progression whose step is 1, 2 or 5 times a power of ten (every value a multiple of the step, inside the view). axisVariable may be one letter other than y (n, P). A pure math graph never uses it. A tick label that collides with the curve (LAYOUT_INVENTORY_INCOMPLETE tick-y-4-label) means: drop that tick value or change the step."],
  [/PIECEWISE_POLY_REFERENCE_CURVE|PIECEWISE_POLY_FUNCTION_NAME_INVALID/,"referenceCurves (piecewise-polynomial-spike-v1) is for a second QUADRATIC drawn with the function: graphPlan.referenceCurves:[{id,name,coefficients:[constant,x,x squared] (exact strings, x squared nonzero),intersectionX:[every crossing x of the function with it]}] (at most two). The vertex of each reference curve must be in requiredPoints (a key point lies on the function or on a reference curve). name and functionName are ONE lowercase letter other than i, x, y (header f(x)=formula, band g(x)=...). A curve equal to a whole piece, a cubic curve or a third curve cannot be drawn: answer UNSUPPORTED."],
  // plane figures (middle school): PLANE_FIGURE_v1, POLAR_POINT, planeMarks
  [/INVALID_POLAR_LENGTH|INVALID_POLAR_ANGLE|INVALID_POLAR_TURN|DEGENERATE_POLAR_REFERENCE|PLANE_FIGURE_/,'POLAR_POINT: inputs [centre, reference] (two different POINT), args {length: positive typedScalar, angleDeg: typedScalar 0<a<360, turn: CCW|CW}; the point lies at that distance on the ray centre->reference turned by the angle. A plane figure uses mathPlan.realization {recipeId:PLANE_FIGURE_v1, unit:source-length, reflectionEquivalent:false}, at least one SOURCE_POINT and no NORMALIZATION_* nodes. A reference direction may be a hidden helper (TRANSLATE_POINT of the centre by (1,0), role DERIVED_INTERMEDIATE, left out of displayPoints).'],
  [/ANGLE_MARK_FACT_MISMATCH|ANGLE_EQUAL_GROUP|ANGLE_ARC_COUNT_INVALID|ANGLE_ARC_TOO_SMALL|ANGLE_MARK_DEGENERATE|ANGLE_MARK_LABEL_REQUIRED|ANGLE_RING_INVALID/,'planeMarks.angles: {id,refs:[A,V,C],value?,label?,side:INNER|OUTER,arcs:1-3,ring:1-3,equalGroup?,noLabel?}. value must equal the angle the points really draw (0.5 degree tolerance): fix the construction (POLAR_POINT angle), not the number. Equal angles share equalGroup and the same arcs count; two groups need different arcs counts. An angle below 5 degrees cannot be marked. Give label (40, x, 2x+10) or value, or noLabel.'],
  [/EQUAL_MARK_|PARALLEL_MARK_|MARK_COUNT_INVALID|MARK_SEGMENT_TOO_SHORT/,'planeMarks.equalLengths / parallels: {id,count,segments:[displaySegment ids, at least 2]}; count 1-3 (equal) or 1-2 (parallel); the segments must really be equal / parallel; two groups of one kind need different counts; a marked segment must be longer than about 40 px (enlarge the figure or mark fewer).'],
  [/ARC_ENDPOINT_NOT_ON_CIRCLE|ARC_SIDE_AMBIGUOUS|ARC_CENTER_MISMATCH|ARC_ENDPOINTS_COINCIDE|FACT_TARGET_NOT_DRAWN|MARK_TARGET_UNKNOWN|MARK_FIELD_UNKNOWN|MARK_ID_DUPLICATE|MARK_ID_INVALID|PLANE_MARKS_/,'planeMarks.arcs: {id,circle:CIRCLE node,center,from,to,side:MINOR|MAJOR|CCW|CW,label?}; from and to must lie on the circle; a half circle needs side CCW or CW. planeMarks.facts: ON_CIRCLE {circle (displayed),points} and TANGENT_PERPENDICULAR {center,contact,tangent: displayed line or segment id}. Every mark id is new (not a node, segment or other mark id); only the documented keys are allowed; every point a mark names must be displayed.'],
  [/PLANE_MARKS_AUDIT_FAIL|MARK_LABEL_OVERLAPS|MARK_LEADER_|ANGLE_LABEL_NOT_IN_ANGLE|SEGMENT_LABEL_AMBIGUOUS_OWNER|ARC_LABEL_INSIDE_CIRCLE|UNDECLARED_MARK/,'The independent plane-marks observer found a mark that does not match the points or the drawing. Fix the plan (the fact or the construction); a label it cannot place without overlap needs a larger figure, fewer labels, or noLabel on the second angle of an equal pair.'],
  [/STAT_BOUNDARIES_INVALID|STAT_CLASS_WIDTH_UNEQUAL|STAT_BOUNDARY_NEGATIVE|STAT_FREQUENCY_COUNT_MISMATCH|STAT_FREQUENCY_INVALID|STAT_FREQUENCY_TOTAL_MISMATCH|STAT_FREQUENCY_TOTAL_ZERO|STAT_RELATIVE_SUM_NOT_ONE|STAT_SERIES_INVALID|STAT_SERIES_NAME_REQUIRED|STAT_HISTOGRAM_ONE_SERIES|STAT_Y_KIND_INVALID|STAT_Y_RANGE_TOO_LARGE|STAT_HIGHLIGHT_INVALID|STAT_VALUES_NEED_ONE_SERIES/,"stat-chart-figure-v1 HISTOGRAM / FREQUENCY_POLYGON: chart {kind,boundaries:[\"20\",\"25\",...] (n+1 class boundaries, strictly increasing, equal class width, 0 or more, at most 12 classes),series:[{name?,frequencies:[integers, one per class],total?} or {name?,relativeFrequencies:[\"0.1\",\"3/20\",...] summing to exactly 1}],yKind?:\"FREQUENCY\"|\"RELATIVE\" (RELATIVE with frequencies makes the engine divide by the total),polygon?:true (histogram only),xTitle?,yTitle?,grid?,showValues?,highlightClasses?}. Copy the numbers of the problem exactly: a frequency list whose length is not the class count, a total that is not the sum, relative frequencies that do not add up to 1, unequal class widths and a histogram of two series are refused. The engine adds the zero-frequency end classes of a polygon itself; never give them. Two series (polygon only) each need a different short name."],
  [/STAT_STEM_PLAN_INVALID|STAT_STEM_VALUE_INVALID|STAT_STEM_TOO_MANY_STEMS|STAT_STEM_KEY_INVALID|STAT_STEM_KEY_NOT_IN_DATA|STAT_STEM_MARK_INVALID|STAT_STEM_SYMBOL_INVALID|STAT_STEM_SYMBOL_DUPLICATE|STAT_STEM_SYMBOL_ORDER_CONFLICT|STAT_STEM_CLASS_[A-Z_]+/,"stat-chart-figure-v1 STEM_LEAF: chart {kind:\"STEM_LEAF\",values:[whole numbers 0-999, the raw data, stem = tens, leaf = ones] or groups:[{name,values},{name,values}] for a back-to-back plot,unitText?:\"건\",title?,key?:{stem,leaf} (a value that exists),marks?:[{group?,ranks:[1-based rank in ascending order]} or {group?,median:true}]}. Give every data value (the engine sorts them, keeps empty stems and counts the leaves); never write stems and leaves by hand. marks circle the rank-th smallest value (a median of an even count circles the two middle values); {group?,rank:10} circles one leaf by rank, a letter leaf included. A leaf the problem names with a letter is a value entry {symbol:\"a\",stem:1,order:3} (one lowercase letter; order = its 1-based place among that stem's leaves in ascending order; the engine never gives it a value; a place beyond the row or repeated, or the same letter twice, is refused). classGroups?:[{group?,from:\"5\",to:\"10\",label?:\"3\"}] brackets the leaves with from <= value < to inside ONE stem row and writes the count the engine counted (a label that differs is refused; a letter leaf the neighbours do not settle inside/outside the interval is refused; an interval over two stem rows or with no leaf is refused). At most 60 values per group and 12 stems."],
  [/STAT_BOX_NEEDS_FOUR_VALUES|STAT_BOX_VALUE_INVALID|STAT_BOX_SUMMARY_INVALID|STAT_BOX_SUMMARY_NOT_ORDERED|STAT_VALUE_NEGATIVE|STAT_STEP_INVALID|STAT_RANGE_TOO_LARGE/,"stat-chart-figure-v1 BOX_PLOT: chart {kind:\"BOX_PLOT\",series:[{name,values:[at least 4 numbers]} or {name,summary:{min,q1,median,q3,max}}] (1 to 3 boxes, names required for more than one),xTitle?,step?,showValues?}. With values the engine computes the quartiles by the curriculum rule (Q1 is the median of the lower half, Q3 of the upper half, the middle value left out when n is odd); with a summary the five numbers must be non-decreasing. Values must be 0 or more; the axis step is chosen for you unless step is given (at most 14 ticks)."],
  [/STAT_SCATTER_POINTS_INVALID|STAT_POINT_OUTSIDE_RANGE|STAT_RANGE_INVALID|STAT_RANGE_NOT_ON_STEP|STAT_LABEL_EVERY_INVALID/,"stat-chart-figure-v1 SCATTER: chart {kind:\"SCATTER\",points:[{x,y,name?}] (name one capital letter, at most 40 points),xRange:[\"lo\",\"hi\"],yRange:[\"lo\",\"hi\"] (0 or more; both ends must be multiples of the step and every point inside),xStep?,yStep?,labelEvery?,xTitle?,yTitle?,grid? (default true),diagonal?:true draws y=x}. Give every plotted point of the original, not only the named ones."],
  [/STAT_DICE_FACES_INVALID|STAT_DICE_CELL_INVALID|STAT_DICE_VARIABLE_INVALID|STAT_DICE_EXPR_INVALID|STAT_DICE_PREDICATE_INVALID/,"stat-chart-figure-v1 DICE_TABLE: chart {kind:\"DICE_TABLE\",faces?:2-8 (default 6),cell?:\"PAIR\"|\"SUM\"|\"PRODUCT\"|\"NONE\",colVar?:\"a\",rowVar?:\"b\",highlight?: predicate}. A predicate is {expr,in:[numbers]} or {expr,cmp:\"=\"|\"<\"|\"<=\"|\">\"|\">=\",value} or {any:[..]} / {all:[..]} / {not:p}; expr uses integers, the two die letters, + - * and parentheses (a+b, b-2*a, a*b). The engine evaluates it on every cell and colours exactly those cells; say the event as a condition, never list the cells."],
  [/STAT_TREE_INVALID|STAT_TREE_LABEL_INVALID|STAT_TREE_TOO_DEEP|STAT_TREE_TOO_LARGE|STAT_TREE_PROBABILITY_INVALID|STAT_TREE_PROBABILITY_MIXED|STAT_TREE_BRANCH_PROBABILITY_SUM|STAT_TREE_PATH_NEEDS_PROBABILITIES/,"stat-chart-figure-v1 TREE: chart {kind:\"TREE\",root:{label?,children:[{label,p?:\"3/7\",children?:[..]}]},showPathProbability?} with 2 to 5 children per node, depth at most 3, at most 12 leaves, labels at most 6 characters. Either every branch has an exact probability p or none does; the probabilities of the children of one node must add up to exactly 1. showPathProbability writes the product along each path at the leaf (needs probabilities)."],
  [/STAT_LABEL_OUT_OF_BOUNDS|STAT_LABELS_TOO_CLOSE|STAT_CHART_RENDERED_LAYOUT_FAIL|STAT_TYPESET_ERROR|STAT_CHART_STATIC_AUDIT_FAIL|STAT_KIND_UNSUPPORTED|STAT_CHART_PLAN_INVALID|STAT_TITLE_INVALID|STAT_MODEL_MISMATCH|STAT_SPEC_ERROR/,"stat-chart-figure-v1: a title longer than about 6 Korean characters, more than about 10 classes or ticks, showValues on a dense chart, or a value label that would touch a polygon line cannot be placed legibly: shorten the title (at most 14 characters), use fewer classes, switch showValues off, or draw one chart per figure. Only the documented keys are allowed in the plan, and kind is one of HISTOGRAM, FREQUENCY_POLYGON, STEM_LEAF, BOX_PLOT, SCATTER, DICE_TABLE, TREE. A pie chart, a bar chart of categories or a cumulative frequency graph is not supported: answer UNSUPPORTED."],
  [/SOLID_(PLAN_INVALID|KIND_UNSUPPORTED|NET_UNSUPPORTED|PARAM_INVALID|UNIT_INVALID|ID_INVALID|COUNT_INVALID|BASE_INVALID|BASE_NOT_SIMPLE|BASE_NOT_CONVEX|BASE_PLANE_UNSUPPORTED|FRUSTUM_TOP_NOT_SMALLER|CONE_SLANT_TOO_SHORT|REGULAR_FACES_UNSUPPORTED|REGULAR_GEOMETRY_INVALID)/,"solid-figure-v1 solids: {kind:\"PRISM\"|\"PYRAMID\"|\"FRUSTUM\"|\"CYLINDER\"|\"CONE\"|\"CONE_FRUSTUM\"|\"SPHERE\"|\"HEMISPHERE\",...} with positive real lengths, at most 3 solids per figure. A prism/pyramid/frustum base is {kind:\"RECT\",width,depth}, {kind:\"REGULAR\",n:3..8,side} or {kind:\"POLYGON\",points:[[u,v],..]} (at most 8 simple points; pyramid and frustum need a convex one; plane:\"XZ\" only for a PRISM = a front face extruded backwards, e.g. a cuboid with a slanted cut). FRUSTUM needs topScale strictly between 0 and 1, CONE_FRUSTUM needs topRadius < radius, a cone net needs slant > radius, unit is cm|mm|m|km. A cube is a PRISM over a RECT base; the tetrahedron, octahedron, dodecahedron and icosahedron are {kind:\"REGULAR_POLYHEDRON\",faces:4|8|12|20,side} and two pyramids on one base are {kind:\"BIPYRAMID\",base,height} (face ids f0.. / top0.. bottom0..; no net, no cuts, no face counting numbers). More than one solid inside another solid, a slanted-plane cut of a prism and 4+ solids in one figure are UNSUPPORTED."],
  [/SOLID_(NAMES_INVALID|NAME_DUPLICATE|NAME_UNKNOWN|DIMS_INVALID|DIM_SEGMENT_NOT_DRAWN|DIM_VALUE_MISMATCH|DIM_NOT_EXPRESSIBLE|DIM_LABEL_INVALID|HIGHLIGHT_INVALID|HIGHLIGHT_NOT_PLANAR|HIGHLIGHT_EDGE_NOT_DRAWN|SEGMENTS_INVALID|SECTION_INVALID|SECTION_UNSUPPORTED|FIGURE_NEEDS_A_LABEL)/,"solid-figure-v1 names and lengths: names is a string of single capital letters in the order base then top (a pyramid: base then apex; \".\" = no name) or {base,top,apex}; a name is used once in the whole figure. dims entries: {edge:\"AB\"} or {from,to} (both must be a drawn edge or a segments entry), {radius:\"bottom\"|\"top\"|\"center\"}, {height:true} (pyramid, frustum, cylinder, cone), {slant:true} (cone, cone frustum), {level:true} (only with section LEVEL); a numeric label must equal the length the model gives, any other label (r, h, 2\\pi r) is a symbol; a length with no exact short form (not an integer, decimal, k*sqrt(m), p/q or k*pi) needs a symbolic label. highlights polygons must be planar and every side drawn; section is {kind:\"AXIAL\"} or {kind:\"LEVEL\",at:\"1/3\"} on a CYLINDER, CONE or CONE_FRUSTUM only. A figure needs at least one name, length or word, or something stressed (a shaded face, segments, a section, marks, a cut, an axis) or a solidCaption (a panel of a composite grid has its panel caption): a bare figure is SOLID_FIGURE_NEEDS_A_LABEL."],
  [/SOLID_NET_(NOT_A_TREE|FACES_NOT_ADJACENT|FACES_OVERLAP|FACE_UNKNOWN)/,"solid-figure-v1 net: faces are named bottom, top (not for a pyramid), side0, side1, ... (side i stands on base edge i). joins is [[alreadyPlacedFace,newFace],...] with exactly (faces - 1) pairs forming a tree, each pair sharing a solid edge; root is the first face. If SOLID_NET_FACES_OVERLAP, hang the faces off different neighbours (a cross layout: strip of side faces, top and bottom on opposite sides)."],
  [/SOLID_(LABELS_NO_ROOM|TYPESET_ERROR|SPEC_ERROR|MODEL_MISMATCH|STATIC_AUDIT_FAIL|RENDERED_LAYOUT_FAIL)/,"solid-figure-v1 layout: a name or length found no free place beside its corner or segment (even with a leader line). Drop some names (use \".\" in names) or lengths, draw fewer solids per figure, or label with a shorter symbol (r, h) instead of a number with a unit. SOLID_STATIC_AUDIT_FAIL means the independent observer disagreed with the final SVG: the errors list names the check (SOLID_EDGE_VISIBILITY_MISMATCH, SOLID_NET_FACE_NOT_CONGRUENT, SOLID_ELLIPSE_AXES_MISMATCH, ...); that is an engine bug, not a plan error: report it."],
  [/PIECEWISE_POLY_REFERENCE_CURVE_(PIECE_COUNT_INVALID|PIECE_INVALID|BREAKPOINT|SOURCE_DOMAIN|DISCONTINUOUS|OUTSIDE_VIEW|FORMULA|CORNER_NOT|EXTREMUM_NOT)|PIECEWISE_POLY_REFERENCE_PIECE_CROSSES|PIECEWISE_POLY_PIECE_COUNT_INVALID/,"referenceCurves now also takes a PIECEWISE second function: {id,name?,pieces:[{coefficients},...] (1 to 4, degree at most 2),breakpoints:[{x,y},...] (one fewer than pieces, the pieces must meet there),sourceDomain?:{kind:\"ALL_REALS\"} or {kind:\"INTERVAL\",range:[lo,hi],states:[\"OPEN\"|\"CLOSED\",...]} (the reference's OWN domain; omit = all reals),formula?,intersectionX:[every x where BOTH functions are defined and equal]}. intersectionX is computed piece pair by piece pair: a root outside either piece's interval, or at an OPEN source end, is never a crossing. Every reference corner and every vertex strictly inside a reference piece must be in requiredPoints; a jump at a reference breakpoint is refused (use a continuous piecewise function or UNSUPPORTED). The main function and each piecewise reference may have at most 4 pieces. The reference's label in the band is g(x)=formula when a formula is given, else g(x); the main function gets f(x) when functionName is given without formula."],
  [/EXPONENTIAL_BASE_|LOGARITHMIC_BASE_|EXP_LOG_PAIR_/,'Exponential/logarithm base: put graphPlan.base as an exact positive integer ("2"), fraction ("1/2") or sqrt(n) with n a square-free integer > 1 ("sqrt(3)"); omit base for e. exp: y=A*base^(k*(x-shiftX))+C with optional exact-integer/fraction shiftX. log: y=A*log_base(k*x+b)+C (argument k*x+b>0). A letter base, base<=0 or base=1, decimals, sqrt(4)/sqrt(8) and nested radicals are refused. Two curves (an inverse pair with the dashed y=x) use capability exp-log-pair-spike-v1 with exactly two curves, each with id/family/base/coefficients/sourceDomain, and identityLine:true; the engine frames the shared window and refuses no-overlap or a window wider than 16. Do not give domain/viewport on a pair plan.'],
  [/UNSUPPORTED_CUBIC_QUARTIC_REPEATED_ROOT_IMPRECISE/,'A repeated real root of a cubic/quartic is a root of a rational quadratic factor (rational or p+q*sqrt(r)), so it is normally representable; this one could not be pinned down tightly enough to draw the touch point at a known x. Rewrite the polynomial in factored form with exact integer/fraction coefficients, or answer UNSUPPORTED for this source.'],
  [/OVERVIEW_(ROOT_NOT_ON_OBSERVED_AXIS|EVEN_ROOT_CROSSES_AXIS|ODD_ROOT_DOES_NOT_CROSS_AXIS|ODD_ROOT_NOT_FLAT|ROOT_NEIGHBOURHOOD_MISSING)/,'The independent observer recomputed the real roots and their multiplicities from the source polynomial and read the final polyline: it must meet the x-axis at every root, stay on ONE side at an even-multiplicity (double/quartic) root, change side with a readable flat band at a triple root. A figure that crosses at a double root or misses the touch point is an engine bug, not a plan error: report it.'],
  [/OVERVIEW_(ROOTS|FEATURES)_BELOW_DISPLAY_RESOLUTION/,'Two distinct roots (or two key features) are closer than one CSS pixel in the audited figure, so the touching/crossing point cannot be read separately. This is UNSUPPORTED: widen the view is not allowed (the framer derives it), so answer UNSUPPORTED for a source whose roots are this close.'],
  [/PIECEWISE_POLY_SAMPLE_NOTE_INVALID|main-curve-name|ref-curve-.*-equation|PIECEWISE_POLY_REFERENCE_ENDPOINT_MARKER_MISMATCH/,'The optional graphPlan.sampleNote shows the parameter value the figure is drawn at (for example "a=2") inside the upper left of the plot: at most 32 characters of digits, letters, = + - * / ( ) . and spaces, and the caption names the same value. A function given only by pieces is named next to its curve (functionName without formula gives f(x); a piecewise referenceCurves entry gives g(x) at its first corner) so the two curves are not confused. The reference curve own domain ends are hollow (OPEN) or filled (CLOSED) dots; they are drawn by the engine and read back by the observer.'],
  [/UNSUPPORTED_CUBIC_QUARTIC_DEGREE/,'Only a degree 3 or 4 polynomial graph is supported by polynomial-spike-v1 (and a repeated real root is fine). A degree 5+ curve, or a cubic/quartic with a restricted source interval, is UNSUPPORTED.'],
  [/ANGLE_MARK_STYLE_INVALID|ANGLE_EQUAL_GROUP_STYLE_MISMATCH/,'planeMarks.angles style: SECTOR (default) fills a small light sector under the arcs; ARC keeps the stroke-only arcs. equalGroup members must also share the same style (two equal angles must look identical).'],
  [/SOLID_ORIENTATION_UNSUPPORTED/,'solid-figure-v1 orientation: APEX_DOWN is only for CONE and CONE_FRUSTUM (a vessel: the point or narrow end rests on the base plane, the wide circle is the rim at height h). radius is still the wide radius; topRadius stays the narrow one. A cylinder, sphere or hemisphere has no APEX_DOWN.'],
  [/SOLID_NEST_(INVALID|UNKNOWN|UNSUPPORTED|DOES_NOT_FIT|CHAIN)/,'solid-figure-v1 nesting: inside:"s1" names a CYLINDER host that is already in solids (lowercase id). Only a SPHERE, CONE or CONE_FRUSTUM can sit inside, with max radius <= the cylinder radius and height <= the cylinder height (a sphere needs 2r <= height). Nested cylinders and a solid hosting another nested solid are refused; draw them side by side instead.'],
  [/SOLID_MARK_(SLANT_UNSUPPORTED|ID_INVALID|UNKNOWN|RAY_NOT_DRAWN|SEGMENT_NOT_DRAWN|NOT_RIGHT_ANGLE|LENGTH_MISMATCH|GROUP_AMBIGUOUS|GROUP_ARC_COUNT|GROUP_MISMATCH|ANGLE_MISMATCH|ANGLE_DEGENERATE)|SOLID_MARKS_INVALID/,'solid-figure-v1 marks: rightAngles [{at,refs:[a,b]}] needs a true 90-degree angle at a named vertex and both rays drawn (an edge or a segments entry); equalLengths [{count,segments:["AB","CD"]}] needs segments of one true length and distinct tick counts 1..3 per group; angles [{refs:[a,vertex,b],value?,arcs,equalGroup?}] needs the 3D angle equal to value (0.5 deg) and distinct arc counts for different groups; equalSlant: true | {solid?,count?} | a list puts the same 1-3 ticks on the left and the right slant of an UNNAMED cone or cone frustum (SOLID_MARK_SLANT_UNSUPPORTED = no such cone, or several and no solid id; its counts differ from every equalLengths count). There are no angle labels and no parallel marks; put the value in dims or the solution text.'],
  [/SOLID_LEVEL_APEX_HIDDEN|SOLID_SILHOUETTE_DEGENERATE/,'solid-figure-v1 projection: for an apex-down vessel the apex projects inside the water-level ellipse when the level is too low (or the cone too flat), so no tangent silhouette exists. Raise the level fraction, or answer UNSUPPORTED for that figure.'],
  [/SOLID_LIQUID_REGION|SOLID_DIM_LINE_MISMATCH/,'solid-figure-v1 observer disagreement about the shaded liquid, the level ellipse or a dimension line: the engine and the plan differ; report it as an engine bug (do not weaken the check).'],
  [/SET_(COUNT_UNSUPPORTED|ID_INVALID|LAYOUT_UNSUPPORTED|SHADE_INVALID|SHADE_EMPTY|ELEMENT_TEXT_UNSUPPORTED|ELEMENT_REGION_EMPTY|ELEMENT_SET_UNKNOWN|TOO_MANY_ELEMENTS|ELEMENT_INVALID|ELEMENT_DUPLICATE)/,'set-diagram-figure-v1 Venn: 1 to 3 sets with distinct single capital letters (not U), elements [{text,in:[set ids]}] whose in lists every set the element belongs to ([] = outside all), and a set expression over U and the ids using union, intersection, difference, parentheses and a postfix complement (^c or the superscript c). An element text that looks like an interval or inequality is not a Venn element. shade true on no cell is refused; B⊂A uses subset:["B","A"] and no element may sit in the empty B-only cell.'],
  [/SET_(ELEMENT_NO_ROOM|LABEL_NO_ROOM|LABEL_OUT_OF_BOUNDS|LABELS_TOO_CLOSE|SPEC_ERROR|MODEL_MISMATCH|DIAGRAM_STATIC_AUDIT_FAIL|DIAGRAM_RENDERED_LAYOUT_FAIL|TYPESET_ERROR)/,'set-diagram-figure-v1 layout: an element text found no room wholly inside its own atomic region, or a set name found no place outside its own circle. Use fewer elements or fewer sets per figure, shorter element texts, or answer UNSUPPORTED. SET_SPEC_ERROR/SET_DIAGRAM_STATIC_AUDIT_FAIL means the independent observer disagreed with the final SVG: report it as an engine bug.'],
  [/MAPPING_(COLUMNS_INVALID|COLUMN_COUNT_UNSUPPORTED|TOO_MANY_ELEMENTS|NEEDS_ARROWS|ARROW_INVALID|ARROW_DIRECTION_UNSUPPORTED|ARROW_DUPLICATE|ARROW_BLOCKS_LABEL|HIGHLIGHT_INVALID|ELEMENT_TEXT_UNSUPPORTED|ELEMENT_OUT_OF_OVAL|COLUMN_NAME_OVERLAPS_OVAL)/,'set-diagram-figure-v1 mapping: 2 or 3 columns {id,name?,elements:[short distinct texts]}, 1 to 8 per column; arrows {from:{column,element},to:{column,element},style?} join adjacent columns in either direction (column and element indices count from 0). A self-map uses two columns with the same name and different ids. Duplicate arrow pairs and non-adjacent columns are refused; an arrow that would cross another element label or an element text that does not fit its oval is refused, so use fewer rows or fewer arrows.'],
  [/TRACE_(RADIUS_INVALID|TARGET_NOT_ON_ARC|TARGETS_DEGENERATE|SPAN_INVALID|LABEL_INVALID)|TRACE_ARC_(MISSING|COUNT_MISMATCH|RADIUS_MISMATCH|DOES_NOT_PASS_THROUGH|SPAN_MISMATCH|DASHED|TOO_THICK|HAS_FILL)|TRACE_LABEL_(MISMATCH|INSIDE_CIRCLE)|TRACE_RADIUS_MISSING/,'planeMarks.traces (compass construction marks): {id,center,radius:{point:pointId} or {segment:segmentId},through:[intersection point IDs],spanDeg?,label?}. center is the compass point, radius is the distance to a point or the length of a displayed segment, and every through point must lie exactly on that radius (TRACE_TARGET_NOT_ON_ARC). The engine draws one thin solid arc of spanDeg degrees (default 24, 2-120) around each intersection; label is an optional construction order digit 1-99 written outside the arc. The observer refuses an arc of another radius, an arc that misses its declared intersection, a dashed or thick arc, and a label that is not the declared digit.'],
  [/NUMBER_LINE_(CONSTRUCTION|ARC|SQUARE)_[A-Z_]+|NUMBER_LINE_RADICALS_MIXED|NUMBER_LINE_VALUES_TOO_CLOSE/,'number-line-figure-v1 constructions: numberLine.constructions (1-4) each {id,center,radius:{value},arc:{side:BOTH|LEFT|RIGHT},hits:[{id,branch:LEFT|RIGHT}],square?:{angleDeg?,side?,uses:RADIUS|DIAGONAL,diagonal?,names?}}. center and hits are POINTS of the same row; radius is an exact value string (sqrt(5), 3+sqrt(5)); every hit must equal center+-radius, and arc side BOTH needs both hits, LEFT/RIGHT the matching one. The optional square stands on the axis at A=center with its side the radius by default (a square of area 5 whose side is the radius), or uses:"DIAGONAL" makes the radius the square diagonal (a unit square with side "1" lands sqrt(2)); diagonal:true draws A-C. A square whose declared side does not explain the radius exactly is refused.'],
  [/SOLID_FACE_LABEL_/,'solid-figure-v1 net face labels: net.faceLabels [{face,text?}] writes one label in the middle of each listed net face (face ids as net.highlights: bottom, top, side0..; a cylinder net has rect, bottom, top; a cone net has sector, base). text omitted writes the exact area with the unit squared; a numeric text must equal that area (SOLID_FACE_LABEL_VALUE_MISMATCH); any other text is a symbol (S, 2\\pi r h: at most 24 characters of letters, digits and _ \\ { } ^ + - = . ( ) and spaces, SOLID_FACE_LABEL_INVALID otherwise). An unknown face (SOLID_NET_FACE_UNKNOWN), a face twice, or an area with no short exact form (SOLID_FACE_LABEL_NOT_EXPRESSIBLE: give text) is refused; a label that finds no room wholly inside its face is SOLID_LABELS_NO_ROOM. A face number or name is a face symbol: ONE circled number (①-⑳), circled Hangul letter, Hangul letter or jamo (가, ㄴ) or such a letter in parentheses ((나)); it is plain text in a box the size of its ink, no area is checked, and it still has to fit wholly inside its face (a narrow triangle face of a flat pyramid net takes it, a long word does not). Opposite-face pairs are not supported.'],
  [/GRAPH_(CONNECTION|SEGMENT|POLYGON)_/,'quadratic graphPlan connections: segments:[{id,from,to,dashed?}] joins two key points or line points of this plan; polygons:[{id,points:[3-6 ids]}] draws the simple closed polygon around them (a triangle on the parabola, a trapezoid of two chords). Both endpoints must be requiredPoints (on the curve) or linePoints (on one of graphPlan.lines); a zero-length segment, a self-intersecting polygon, an endpoint outside the viewport or a repeated id is refused. The independent observer recomputes each endpoint and reads the drawn lines back.'],
  [/PLANE_MARKS_UNSUPPORTED_ON_GRAPH/,'planeMarks and dashed/arrow displaySegments belong to a construction plan. A coordinate figure is mathPlan.realization {recipeId:SOURCE_COORDINATE_AXES_v1, unit:source-coordinate, reflectionEquivalent:false} (axes drawn, SOURCE_COORDINATES); the same angles/equal ticks/parallels/arcs/facts/regions work there. A function graph cannot take planeMarks.'],
  [/OVERLAY_(PLAN|ID|POINT|CURVE|LINE|SEGMENT|GUIDE|POLYGON|FILL|VALUE|LABEL|BASE|TOO_MANY)/,'graphPlan.overlays draws elements on top of any single-curve graph: lines {id,slope,intercept} or {id,x} (vertical), named points ({id,curveX} on the curve, {id,intersect:[lineA,lineB]}, {id,axis:"x"|"y",value}, {id,x,y}), segments {id,from,to,dashed?}, dashed guides {id,from,axis:"x"|"y"|"BOTH"}, and simple polygons {id,points,fill?}. Use exact integer/fraction/sqrt strings only; a point on the curve must be inside the drawn source domain and every point/vertex inside the framed viewport (the engine does not enlarge the frame for overlays). For exp-log-pair give curve:"<curve id>" on a curve point. OVERLAY_POINT_ID_CONFLICT means the id repeats a requiredPoints id; OVERLAY_LINE_PARALLEL means two overlay lines meet no unique point. The independent observer recomputes each overlay element from the raw plan and reads it back from the final SVG.'],
  [/PIECEWISE_(DISCONTINUOUS|DISCONTINUITY|ENDPOINT_STATE|VALUE_CONFLICT|TOO_MANY_PIECES|REFERENCE_LINE|INTERSECTION|MISSING_VALUE)|STEP_INTERVAL_INVALID/,'piecewise-discontinuous-spike-v1 (a function with jumps, holes and isolated points): graphPlan {family:"piecewise-discontinuous",pieces:[{coefficients,domain:[lo,hi],start:"OPEN"|"CLOSED",end}],jumpValues:[{x,y}],referenceLines,requiredPoints}. Pieces are ordered, do not overlap, and only the first left end and last right end may be null (unbounded). At a shared breakpoint exactly one function value must be declared: make one of the two joining ends CLOSED, or give jumpValues {x,y} there (PIECEWISE_DISCONTINUITY_UNDECLARED); a jump value that contradicts a CLOSED end is PIECEWISE_VALUE_CONFLICT; two CLOSED ends at one x is PIECEWISE_DOMAIN_OVERLAP. jumpValues also draws an isolated point f(a)=c. A staircase is step:{values,xFrom,xTo} (equal subintervals, left-closed right-open, the last closed at xTo, at most six steps; a bad interval is STEP_INTERVAL_INVALID). Endpoint dots are computed by the engine: never list them. referenceLines are horizontal y=c only, and intersectionX must list every crossing including a declared value on the line.'],
  [/TRIG_(INTERVAL_REQUIRES_RATE_PI|RATE_PI_REQUIRES_PLAIN_INTERVAL|INTERVAL_PI_PHASE_MUST_BE_PI|PHASE_RATIONAL_REQUIRES_INTERVAL|TAN_REFERENCE_LINES_UNSUPPORTED|TAN_POLE_AT_INTERVAL_END|TAN_INTERVAL_NO_POLE|TAN_REQUIRES_PI_PHASE|KEY_POINTS_REQUIRE_[A-Z_]+|KEY_POINTS_TOO_MANY|TICK_PI_REQUIRES_PI_AXIS|PI_TICK_[A-Z_]+|GRAMMAR_UNSUPPORTED)|INVALID_TRIGONOMETRIC_(RATE|PHASE)/,'trigonometric general parameters (additive v2 grammar): ratePi is an exact rational m and the rate is m*pi, with coefficients [A,C] (a plain rational rate keeps coefficients [A,k,C]). phasePi is a multiple of pi, phase is a plain radian value; give exactly one. A plain x axis (months/time) is sourceDomain {kind:"INTERVAL",range:[lo,hi],states:[start,end]} and requires ratePi; INTERVAL_PI keeps the pi-unit axis and refuses a rate carrying pi. TAN may span several branches: a dashed pole is drawn at every asymptote strictly inside the interval, so the interval may not end on a pole and tan takes no referenceLines. keyPoints:true marks every exact extremum and midline crossing (SIN/COS, pi-multiple phase). axisTickPi:true (pi-unit axis) reads axisTickValues.x as exact multiples of pi and labels pi/2, pi, 3*pi/2; on a plain axis it is refused.'],
  [/SQRT_(GENERAL|AFFINE_GENERAL|AMPLITUDE|SIGN|OFFSET|SOURCE_INTERVAL|DRAW_INTERVAL|REQUIRED_POINT)|INVALID_SQRT_(AFFINE_COEFFICIENT|AMPLITUDE|SIGN|OFFSET|VIEWPORT)|UNSUPPORTED_SQRT_(AFFINE_GRAMMAR|AFFINE_SLOPE|NUMERIC_SCOPE)|REQUIRED_SQRT_POINT_|EXACT_COORDINATES_/,'General square-root y=q+s*k*sqrt(a*(x-p)): keep radicand [constant,a] (exact integer/fraction or p+q*sqrt(r), ONE radical in the plan, a nonzero), and add optional amplitude k>0 (default 1), sign s = 1 or -1, offset q. The starting point (p=-constant/a, q) is a closed dot; a>0 opens right (x>=p), a<0 opens left (x<=p); s*k>0 runs up, s*k<0 runs down. sourceDomain NATURAL_SQRT_AFFINE draws the whole branch; CLOSED_INTERVAL range [lo,hi] must lie inside the natural domain and graphPlan.domain must equal it. requiredPoints must lie on the curve; exactCoordinates {id:[xText,yText]} prints exact coordinate labels and must agree with x,y. domainRangeLabels:true writes the domain/range inequalities. Fix the coefficient/sign/interval; a second curve, a line or a region is another capability (UNSUPPORTED).'],
  [/NUMBER_LINE_SYMBOL_[A-Z_]+/,'number-line-figure-v1 symbol row: a value-free letter row {kind:"SYMBOLS",points:[{id,order,sign,name?}]} marks letters in their left-to-right order (sign NEG left of 0, POS right of 0; negatives must come before positives). id and name are one lowercase letter, optional name may start with a minus sign (-a); order 0..n-1 is unique; the figure prints only 0 and the letters, never a number.'],
  [/NUMBER_LINE_(POINT_NAME_(INVALID|DUPLICATE)|SUBDIVISIONS_INVALID|TICKS_TOO_DENSE|AXIS_VARIABLE_INVALID)/,'number-line-figure-v1 POINTS row notation (a row holds 2 to 8 points): a point name is one capital letter or ONE Hangul consonant letter (ㄱ..ㅎ) as the id or as "name":"ㄱ"; "name":null or "hideName":true draws no name (never both a name and hideName:true; two points of a row cannot share a Hangul name); "showValue":false leaves the point value out (the point and its name are still drawn). "subdivisions":[{"from":"-3","to":"-2","parts":3}] (integer strings from<to, parts 2 to 10, at most 8 entries, no overlap, only on a POINTS row) cuts each unit between from and to into equal parts and labels every integer tick of the row; too many parts for the width is NUMBER_LINE_TICKS_TOO_DENSE (fewer parts or a shorter range). "band":false drops the highlighted segment between the outermost points; numberLine "axisVariable":false drops the variable at the axis end (a boolean).'],
  [/INVALID_HIDDEN_POINT_NAMES|INVALID_HIDDEN_POINT_STYLE|HIDDEN_POINT_(STYLE_REQUIRES_PLANE_FIGURE|STYLE_WITHOUT_HIDDEN_POINTS|NAMED_IN_TEXT)|HIDDEN_POINT_MARKER_|UNEXPECTED_POINT_MARKER|UNMARKED_POINT_UNKNOWN/,'hiddenPointNames:[point IDs] draws points without a name; each id must be a displayed point and not in coordinateLabels or pointNames. A DERIVED_INTERMEDIATE point works anywhere; a SOURCE_POINT (a point the source figure never names) only on a PLANE_FIGURE_v1 plan, and then no caption or label text (angles/arcs/regions label, expressionLabels text, scalarLabels prefix) may write its id. hiddenPointStyle is "DOT" (default, a bare dot) or "NONE" (no dot at all, plane figure with hidden points only). If the observer reports HIDDEN_POINT_MARKER_* or UNEXPECTED_POINT_MARKER, the final SVG draws a dot where the plan says none.'],
  [/SOLID_NET_(HIGHLIGHT_INVALID|SEGMENT_INVALID|SEGMENT_DUPLICATE|EDGE_UNKNOWN|EDGE_AMBIGUOUS|EMPHASIS_UNSUPPORTED)/,'solid-figure-v1 net emphasis (polyhedron nets only): net.highlights [{face:"side2",fill:"LIGHT"|"MEDIUM"}] tints a whole net face (faces are bottom, top, side0.., once each); net.segments [{face:"side0",edge:0}] or [{from:"B",to:"C"}] (corner names written in net.corners; a name pair that is at two different net edges is ambiguous, use face+edge) with role "ACCENT" (red, default) or "REF" (bold black) stresses one edge. The same fold written from both faces is a duplicate. A cylinder or cone net takes neither.'],
  [/SOLID_COUNT_(REQUEST_INVALID|FACES_UNSUPPORTED|UNSUPPORTED|NAMES_CONFLICT|TOO_MANY)|SOLID_COUNT_(LABEL|NUMBERS|TEXT|ON_VERTEX)/,'solid-figure-v1 counting numbers: on a PRISM, PYRAMID or FRUSTUM item put count:{vertices:true,edges:true} (only the ones you need; faces cannot be counted) to number the vertices 1, 2, ... and the edges with circled numbers beside their midpoints (hidden edges too; around the base ring, up the sides, around the top ring; at most 20 edges). Numbered vertices must be unnamed: names "........". A round solid takes no count. If a number finds no room (SOLID_LABELS_NO_ROOM) count only the edges or only the vertices, or draw a larger solid.'],
  [/PANEL_SOLID_(PLAN|MIXED)_\d+/,'composite-panels-v1 with solid panels: a solid panel is a plain solid-figure-v1 plan (solids or net) WITHOUT caption/solidCaption/sourceConditions/newVisualInformation/sourceQuote and without panelWidth (the grid sets it); put the explanation in the panel caption and the composite top level. A solid panel may sit beside PLANE_FIGURE_v1 panels or other solid panels (2-4 panels in all), never beside a graph or number-line panel.'],
  [/SOLID_SOURCE_QUOTE_INVALID/,'solid-figure-v1 sourceQuote must be a non-empty string (at most 200 characters) copied from the item; it is provenance only and never drawn.'],
  [/SOLID_NET_DIAGONAL_|SOLID_NET_SEGMENT_PLAN_(INVALID|UNRESOLVED)/,'solid-figure-v1 net face diagonal: net.segments takes {face:"top",diagonal:[1,3],role?:"ACCENT"|"REF"} (two non-neighbouring corners of that face in its cycle order, drawn as a new bold line) or {from:"N",to:"L"} when those two names are at non-neighbouring corners of one face and no drawn edge joins them; neighbours are an edge, not a diagonal. A SOLID_NET_DIAGONAL_* observer error means the final SVG and the plan disagree (engine bug, do not weaken the check).'],
  [/SOLID_NAMES_INVALID|SOLID_NAME_DUPLICATE/,'solid-figure-v1 names: one vertex may carry several names as a names LIST entry "M,A,I" (2-4 capital letters, optional prime); names must be unique over the whole figure; a letters STRING ignores commas ("A,B,C" is "ABC"), so write several names only as list entries.'],
  [/SOLID_CUT_|SOLID_NET_UNSUPPORTED:CUT|SOLID_COUNT_UNSUPPORTED:CUT/,'solid-figure-v1 cuts: on a PRISM/PYRAMID/FRUSTUM item write cuts:[{through:[["AD","1/2","M"],["BC","1/2","N"],["CG","1/2","P"],["DH","1/2","Q"]],keep?:"F"}] (1-2 planes, convex solids only). through = points on DIFFERENT edges of the solid as it is at that cut: [edge as its two vertex names, "p/q" from the first named vertex (0<p/q<1), optional new-vertex name]; vertices:["A","C","F"] adds corners of the solid as points of the plane (names; in the first cut also references "#b0" "#t2" "#apex" "#v5" of the uncut solid: SOLID_CUT_VERTEX_REF_UNSUPPORTED in a second cut, SOLID_CUT_VERTEX_UNKNOWN = no such corner now, a corner already cut away included); 3-6 points in all, coplanar, and the plane must cut something off. A plane through the three neighbours of a corner cuts only that corner off and adds no vertex (cuboid: 7 vertices); to see the section lit use highlights:[{polygon:[the three corners]}]. The side with more vertices stays; equal numbers need keep:"<a vertex that stays>"; names of removed vertices cannot be used later; no count, no height dim, no net, no round solid with cuts.'],
  [/CONTAINER_(PLAN_INVALID|PAIR_COUNT_INVALID|PROFILE_INVALID|PIECE_KIND_UNSUPPORTED|CURVED_PROFILE_UNSUPPORTED|ASYMMETRIC_UNSUPPORTED|APEX_UNSUPPORTED|DIMENSION_INVALID)/,'container-fill-figure-v1 vessel: container:{pairs:[{vessel:{name?,profile:[pieces bottom to top, 1 to 4]},graphName?,segmentNotes?,flowPi?,xTicks?,yTicks?}],guides?,xTitle?,yTitle?,origin?} with 1 to 3 pairs. A piece is {kind:"CYLINDER",radius,height} or {kind:"FRUSTUM",r0 (bottom),r1 (top),height}, exact positive strings; r0 "0" (a cone point down) only on the first piece; a point at the top is refused. Only these two kinds on one vertical axis: a sphere, hemisphere or curved bottle, a tilted or off-axis vessel and an inflow that changes with time cannot be drawn: answer UNSUPPORTED. Never draw the curve; the engine computes the height-time graph.'],
  [/CONTAINER_(NAME_INVALID|FLOW_INVALID|XTICKS_NEED_FLOW|TICK_INVALID|SEGMENT_NOTE_INVALID|TITLE_INVALID)/,'container-fill-figure-v1 text and ticks: name and graphName at most 6 characters; xTitle/yTitle at most 14 characters (write units yourself: "시간(초)", "높이(cm)"); segmentNotes [{segment (0 = bottom piece, no repeats),text (at most 16 characters)}]; numeric ticks only where you give a value: yTicks (heights, increasing, at most the vessel height) and xTicks (times, increasing, at most the total time) which need flowPi (the water volume per time unit as a multiple of pi, "9" = 9 pi per second).'],
  [/CONTAINER_(PROPORTION_UNSUPPORTED|NOTE_NO_ROOM|GUIDE_HIDDEN|LABEL_OUT_OF_BOUNDS|LABELS_TOO_CLOSE|LABEL_ON_LINE|SPEC_ERROR|TYPESET_ERROR|MODEL_MISMATCH)|CONTAINER_FILL_(STATIC_AUDIT_FAIL|RENDERED_LAYOUT_FAIL)/,'container-fill-figure-v1 layout: a piece under 12 px high, a part narrower than 6 px or two kinks under 8 px apart cannot be drawn legibly (give the proportions of the picture, for example a neck of radius 1 under a body of radius 3, not 1 against 30); a note that finds no room needs shorter text (at most 16 characters, fewer notes) and a title longer than about 5 Korean characters runs off the right edge; use fewer pairs (three rows is the most) or shorter names.'],
  [/SCALAR_LABEL_VALUE_(MISMATCH|INVALID)|SCALAR_LABEL_REQUIRES_SEGMENT_LENGTH/,'planeMarks.scalarLabels[].value: give the exact length text (e.g. "2*sqrt(5)" or "13/2") of a SEGMENT_LENGTH label whose endpoints are derived points; the engine recomputes the length and refuses a value that differs (MISMATCH) or does not parse (INVALID). value is only for kind SEGMENT_LENGTH.'],
  [/ANGLE_EMPHASIS_GROUP_INVALID|INVALID_ANGLE_EMPHASIS_GROUP|ANGLE_EMPHASIS_COLOR_MISMATCH|ANGLE_EMPHASIS_UNDECLARED/,'planeMarks.angles[].emphasisGroup is an integer 1-3 (1 red, 2 blue, 3 green): angles with the same value get arcs of the same colour, separate from equalGroup (arc count). Use it when one angle belongs to two relations (corresponding pair and vertical pair). An observer COLOR_MISMATCH/UNDECLARED means the SVG arc colour disagrees with the plan (engine bug, do not weaken the check).'],
  [/INVALID_UNMARKED_POINT_NAMES|UNMARKED_POINT_NAMES_WITH_STYLE_NONE/,'unmarkedPointNames:[ids] drops the dot of only these hidden points (e.g. the feet of perpendiculars on the axes) while other hidden points keep their dot; it must be a non-empty, duplicate-free subset of hiddenPointNames and cannot be combined with hiddenPointStyle "NONE". On a coordinate figure hiddenPointNames may now include SOURCE_POINT ids (name hidden, point kept).'],
  [/ANGLE_LABEL_(LEADER_CROSSES|IN_OTHER_ANGLE|TOO_FAR)/,'Angle labels that do not fit inside their angle are placed outside with a leader that starts on that angle\'s own arc (or arc end) and crosses no stroke. LEADER_CROSSES / IN_OTHER_ANGLE / TOO_FAR are observer errors on the final SVG: give the figure more room (longer rays, larger canvas), drop a non-essential label (noLabel) or move a value to a caption; never weaken the check.'],
  [/STAT_HIGHLIGHT_(UNKNOWN_CLASS|POINT_INVALID)|STAT_RESTORED_(INVALID|UNSUPPORTED|NEEDS_TOTAL)|STAT_HIDE_VALUES_INVALID|STAT_UNKNOWN_NEEDS_TOTAL|STAT_CLASS_SUM_[A-Z_]+|STAT_VALUE_LABEL_NO_ROOM|STAT_STEM_RANK_LABELS_INVALID/,"stat-chart-figure-v1 marks of a solution figure. A frequency the problem does not show is null in frequencies/relativeFrequencies (no bar, polygon broken there; RELATIVE from frequencies needs total). highlightClasses entries are a class, {class,tone:1|2} or a group {classes:[..],tone}: bars of a histogram, or the points of every series of a FREQUENCY_POLYGON; never a null class. highlightPoints:[{series?,class,tone?,showValue?}] rings (tone 1) or enlarges (tone 2) single polygon points (polygon charts only, no duplicates, not together with showValues when showValue is used). restoredClasses:[i] (HISTOGRAM without polygon, needs the stated total, not a null class) draws the bar dashed and leaves its value unwritten unless showRestoredValues; hideValues:[i] (needs showValues) leaves one bar's value out. classSums:[{series?,from,to,label?,unit?}] brackets classes from..to under the axis: a numeric label must equal the exact sum (hidden classes count only when one bracket holds all of them and total says what they add up to; otherwise label \"?\" or none); at most one bracket per class and series, unit 1-3 letters. A value label that has no free place near its point is refused (STAT_VALUE_LABEL_NO_ROOM): write fewer values. STEM_LEAF: rankLabels \"FROM_LARGEST\"|\"FROM_SMALLEST\" needs marks (at most 16 circled leaves)."],
  [/SOLID_SPHERE_CUT_/,'solid-figure-v1 sphere cut: on a SPHERE item write cut:{kind:"HALF"|"QUARTER"|"OCTANT"|"THREE_QUARTERS"|"SEVEN_EIGHTHS",facing?:"CUT"|"CURVED"} = the sphere cut by planes THROUGH ITS CENTRE (offset, if written, must be 0); only a SPHERE takes it (not HEMISPHERE/CYLINDER/CONE), never with inside or count. Two halves shown apart = two HALF solids (ids s1, s2) side by side; there is no cut.explode. dims {radius:"center"} (add solid:"s1" when several solids) needs a seen radius, so keep facing "CUT" (the default). A plane that misses the centre, a cap/segment of a sphere or any other piece: answer UNSUPPORTED.'],
  [/SOLID_HIGHLIGHT_(FACE_|FILL_)|SOLID_HIGHLIGHT_INVALID/,'solid-figure-v1 highlights: one entry is {polygon:[named vertices of one plane]} OR {face:"top"|"bottom"|"side0"...,solid?:"s1",fill?:"LIGHT"|"MEDIUM"|"WARM"|"GREEN"|"ROSE"|"VIOLET"} (never both; fill also on the polygon form; at most 8; the same face once). face shades a whole face of a PRISM/PYRAMID/FRUSTUM with NO vertex names needed (side i stands on the i-th base edge; a pyramid has no top); with several polyhedra write solid; a solid with cuts, a round solid or an unknown face name is refused. A hidden face is shaded through the faces in front of it: keep one tint for hidden faces.'],
  [/SOLID_SECTION_(UNSUPPORTED|INVALID)/,'solid-figure-v1 section: AXIAL (the plane through the axis) is for a cylinder, cone or frustum only; LEVEL at:"p/q" (0<p/q<1, p/q of the height) works on those and also on a WHOLE sphere or hemisphere (not nested, no cut): a circle of radius sqrt(R^2-(z-zc)^2), with no fill and no level or radius-level dims on a ball. A plan with no rotation solid takes the first sphere or hemisphere; name another with section.solid.'],
  [/SOLID_SECTION_FILL_/,'solid-figure-v1 section fill: section:{kind:"LEVEL",at:"1/2",fill:"BOTTOM"|"TOP"} shades the body below (a frustum cut off a cone) or above (the small cone) the level plane of an APEX-UP cone, frustum or cylinder. An apex-down vessel already shades its liquid (no fill), AXIAL takes no fill, other fill values are refused.'],
  [/SOLID_VREF_/,'solid-figure-v1 vertex references: where the source figure shows no vertex names do not invent letters; set names to "........" (all dots) and write a vertex as "#b0" (i-th vertex of the base ring, 0-based, base polygon order), "#t2" (i-th of the top ring of a PRISM/FRUSTUM), "#apex" (PYRAMID apex) or "#v5" (i-th vertex in model order: counting number k is #v(k-1); render with count:{vertices:true} to see it), in segments from/to, dims edge/from/to (edge as ["#b1","#t1"]), highlights polygon and marks at/refs/equalLengths. With several polyhedra put the solid id in front ("s2#b0"; SOLID_VREF_AMBIGUOUS otherwise). SOLID_VREF_UNKNOWN = no such vertex (index too large, #t on a pyramid, #apex on a prism); SOLID_VREF_UNSUPPORTED = a round solid or a solid with cuts has no slots (name its vertices instead).'],
  [/SOLID_(AXIS_|LABELS_INVALID|LABEL_(TEXT|AT|EDGE|FACE|AXIS|SLANT|DUPLICATE)|LABELS_UNSUPPORTED)/,'solid-figure-v1 words and axis: write a word the SOURCE figure shows (never invent a, h or vertex numbers): labels:[{text:"회전축",at:...}] (at most 6; text 1-12 characters of Hangul, letters, digits, spaces, parentheses, a middle dot; no TeX) with at = a vertex name or reference ("A", "#apex"), {axis:true} (rotation solid: its axis is drawn), {slant:true} (cone or cone frustum), {edge:["#b1","#b2"]} (a drawn edge or segment) or {face:"side0"} (a face that faces the viewer, an uncut polyhedron; add solid:"s1" when there are several solids); one word per target, none on a net. A rotation solid may also say axis:true or axis:{label:"회전축"} (dash-dot line 14 percent longer than the solid at both ends; not on a sphere, hemisphere or nested solid). A hidden face is SOLID_LABEL_FACE_HIDDEN: label a face that shows (top, side0, side1 of a cuboid).'],
  [/SOLID_EDGE_LABEL_/,'solid-figure-v1 net edge labels (polyhedron nets only): net.edgeLabels [{face,edge,text?}] (at most 10) writes at the edge-th side of a face (0-based, the face cycle order of dims) like net.dims and is numbered after it: no text = the exact length with the unit, a TeX text = a number that must equal the length (SOLID_DIM_VALUE_MISMATCH) or a symbol (a), a text with Hangul (at most 12 characters of Hangul, letters, digits, spaces, parentheses, a middle dot: 밑변) = a word that only names the edge. SOLID_EDGE_LABEL_INVALID = wrong shape, count, edge number or word; a cylinder or cone net takes none (use dims part).'],
  [/SOLID_(BALLS_|NEST_OVERLAP)|SOLID_NEST_UNSUPPORTED:MIXED/,'solid-figure-v1 balls in a cylinder: on the CYLINDER item write stack:{count:3,radius:3} (2-6 equal balls resting on each other from the bottom: centres at r, 3r, 5r, ...) OR inside:[{kind:"SPHERE",radius,centerZ?}, ...] (centerZ = height of the ball centre; omitted: the ball rests on the one before it, the first on the bottom). The balls become spheres s1b1, s1b2, ... of cylinder s1, so a radius goes on one ball with dims:[{solid:"s1b1",radius:"center"}]. Every ball must fit (radius <= cylinder radius, between bottom and top: SOLID_NEST_DOES_NOT_FIT:<ball id>) and no two may overlap (centre distance >= sum of radii: SOLID_NEST_OVERLAP:<id>,<id>); several guests of one cylinder must all be spheres (SOLID_NEST_UNSUPPORTED:MIXED). stack and inside:[...] together, a count outside 2-6, an unknown key or a ball that is not a SPHERE is SOLID_BALLS_INVALID; a host that is not a CYLINDER is SOLID_BALLS_UNSUPPORTED. A single nested sphere may also be written inside:"s1" with centerZ.'],
  [/SOLID_NET_RIGHT_ANGLE_/,'solid-figure-v1 net right angles (polyhedron nets only): net.rightAngles [{face,corner}] draws a small square at corner `corner` of the face (0-based, in the face cycle order as net.segments diagonal uses it: counter-clockwise seen from outside, so the bottom face of a prism runs the other way round). The two edges there must be perpendicular (SOLID_NET_RIGHT_ANGLE_NOT_RIGHT:<face>:<corner>:right_at=<the right corners of that face>: use one of those), at most 6, one per corner; a cylinder or cone net has none (SOLID_NET_RIGHT_ANGLE_UNSUPPORTED).'],
  [/SOLID_NET_EXCLUDED_/,'solid-figure-v1 net excluded circles: net.excluded ["bottom","top"] (cylinder net) or ["base"] (cone net) draws those circles dashed and grey = not part of the surface (two hemispheres glued to a cylinder, a cone-shaped hat with no bottom); every listed part once, nothing else (SOLID_NET_EXCLUDED_INVALID). A polyhedron net takes no excluded faces (SOLID_NET_EXCLUDED_UNSUPPORTED:POLYHEDRON).'],
  [/DIMENSION_(SIDE_INVALID|SIDE_AMBIGUOUS|STYLE_INVALID|OFFSET_INVALID|LABEL_REQUIRED|POINTS_COINCIDE|POINT_REFS_REQUIRED|TOO_SHORT|BRACE_TOO_NEAR|REQUIRES_EQUAL_UNITS|FACT_MISMATCH)/,'planeMarks.dimensions:[{id,from,to,label,unit?,side,style?,offset?,value?}]: from/to are two different displayed points; side is the SCREEN side ABOVE|BELOW|LEFT|RIGHT (a horizontal segment takes ABOVE/BELOW, a vertical one LEFT/RIGHT; a segment nearly perpendicular to the named side is DIMENSION_SIDE_AMBIGUOUS); style BAR (default) | ARROW | BRACE; offset 1..3 (integer) stacks several on one side; label is required (math text up to 40 characters, with unit cm|mm|m or written "24\\\\,cm"); a dimension is at least 40 px long on the canvas (BRACE longer: enlarge the figure or use BAR); value, when given, must be the real distance between the two points in plan units.'],
  [/DIMENSION_(PART_MISSING|PART_UNEXPECTED|PART_SHAPE|OFFSET_MISMATCH|SIDE_MISMATCH|END_MISMATCH|EXTENSION_MISMATCH|TICK_MISMATCH|ARROW_MISMATCH|BRACE_MISMATCH|LABEL_NOT_OUTSIDE|LABEL_OFF_CENTER|LABEL_TOO_FAR|LABEL_AMBIGUOUS_OWNER|CROSSES_STROKE)/,'The observer recomputed the dimension from the points and the final SVG and a part is wrong (or the dimension line crosses another stroke: DIMENSION_CROSSES_STROKE): put the dimension on the other side (side), give it another offset, or move the stroke it crosses; two dimensions on one side need different offsets (a label cannot sit between two lines that are closer than its height).'],
  [/PATH_LABEL_(POINTS_INVALID|SEGMENT_NOT_DRAWN|LABEL_REQUIRED|FACT_MISMATCH|LEADER_MISSING|LEADER_CROSSES)/,'planeMarks.pathLabels:[{id,points,label,unit?,labelKind?,value?}]: points are 3 to 8 DIFFERENT displayed points, and every consecutive pair must already be a displaySegment (PATH_LABEL_SEGMENT_NOT_DRAWN:<id>:<a>-<b>); one label for the whole path length with a leader that starts on the path; value (optional) is the sum of the consecutive distances. A straight distance between two points is a dimension, not a path label.'],
  [/ANGLE_LABEL_PLACEMENT_(INVALID|NEEDS_LABEL)|ANGLE_LABEL_LEADER_MISSING|ANGLE_LABEL_NOT_OUTSIDE_ANGLE/,'planeMarks.angles[].labelPlacement is "AUTO" (default) or "LEADER" (the label stands OUTSIDE its angle on a leader from its own outermost arc); LEADER needs a label (not noLabel). If LEADER finds no room (LAYOUT_INVENTORY_INCOMPLETE) use AUTO, a larger coordinateCanvas, or longer rays. Angles that share a vertex take ring 1..3 to keep their arcs apart.'],
  [/TRACE_(JOIN_TOO_WIDE|LABEL_AT_INVALID|LABEL_AT_NEEDS_LABEL|LABEL_NOT_AT_ANCHOR|JOIN_SPAN_MISMATCH)|TRACE_SPAN_INVALID/,'planeMarks.traces[].span is only "JOIN" (one continuous arc through all stated intersections, spanDeg/2 past each end, at most 300 degrees in all: split the trace otherwise); labelAt is "START"|"MID"|"END" (counter-clockwise start, middle, end of the drawn arc) or a number of degrees (0 right, 90 up) and needs a label.'],
  [/SEGMENT_LABEL_AT_INVALID|SEGMENT_LABEL_NOT_AT_END/,'planeMarks.expressionLabels[].labelAt is "START" (the first ref of the owner segment), "MID" (default) or "END" (the second ref): the label stands at that end of its segment.'],
  [/TEXT_LABEL_|MARK_FIELD_INVALID:textLabels/,'planeMarks.textLabels:[{id,at,text,labelKind?,anchor?,factRole?}] writes a short label that no mark owns. at is a source coordinate [x,y] (the label is centred there, anchor CENTER) or the id of a displayed point (beside it, on the side anchor names: N NE E SE S SW W NW). text is one line of at most 40 characters: with a Hangul syllable it is plain text (TEXT), otherwise a formula (MATH) of letters, digits, spaces and ( ) , < > = + - . only (no fractions, powers, roots or function names). A (x,y) number written beside a point must be that point\'s real coordinates (TEXT_LABEL_COORDINATE_MISMATCH).'],
  [/NUMBER_LINE_(ROW_LABEL_INVALID|ROW_LABEL_TOO_WIDE|POINT_STYLE_INVALID|WITHIN_INVALID)/,'number-line-figure-v1 rows: label is one plain line of at most 6 characters written left of that row\'s axis (every axis then starts further right; NUMBER_LINE_ROW_LABEL_TOO_WIDE means the typeset label did not fit its column: shorten it). A POINTS point style is FILLED (default), HOLLOW (open circle) or CROSS (x). A POINTS row may carry within:k, the 1-based number of an EARLIER SET or RESULT row: each of its points is then classified exactly against that row\'s set (inside: filled with a ring, outside or on an open end: CROSS unless style is given). within on a SET/RESULT row, a forward reference or a reference to a POINTS row is NUMBER_LINE_WITHIN_INVALID.'],
  [/STAT_UNKNOWN_LABEL_|STAT_SHOW_END_VALUES_UNSUPPORTED/,'stat-chart-figure-v1 HISTOGRAM: unknownLabels:[{class,label}] draws a dotted outline with a symbol in a class whose frequency is null (the problem erased it); label is at most 10 characters of letters, digits and + - = ( ) ? (no fractions, no Hangul); the class must be null and listed once; polygons do not take it. showEndValues:true (one-series polygon chart only) writes 0 at the two zero end points. A classSums label that is not a plain number (6명, 합계) is a stated fact written as given (no unit field); a bare number must be a sum the engine can derive.'],
  [/ANGLE_STRAIGHT_|ANGLE_SUM_|RIGHT_ANGLE_LABEL_/,'planeMarks.angles[] with straight:true is the half turn between the two rays of a straight line a-v-b (v in the middle, 0.5 degrees): side must be ABOVE, BELOW, LEFT or RIGHT (the screen side its semicircle faces; the side must not run along the line); use ring 3 and style ARC to enclose neighbouring angles. planeMarks.angleSums:[{id,angles:[idA,idB],label?,at?,anchor?}] writes A+B=S from two angle rows at ONE vertex that both declare value; label (the sum) must equal it. rightAngles[].label is an expression of letters, digits, spaces and ( ) , < > = + - . degree sign only (no Hangul, no function names).'],
  [/MARK_FIELD_(UNKNOWN|INVALID):commonSides/,'planeMarks.commonSides:[{id,segment,text?,labelAt?,factRole?}] writes 공통 (or your own plain text of at most 6 characters) beside the drawn segment named by segment (an id of displaySegments); labelAt is START, MID (default) or END. Other keys are not accepted.'],
  [/AXIS_SCALE_|INVALID_AXIS_SCALE|EQUAL_UNIT_SCALE_MISMATCH/,'graphPlan.axisScale:{x,y} (piecewise-polynomial only) gives each axis its own scale for a graph whose axes measure different things (minutes against kilometres): x and y are positive integers, decimals or fraction strings, and only their proportion counts ({x:1,y:12} draws one y unit twelve times as long as one x unit; the proportion stays within 1:64 and 64:1). It replaces the automatic squeeze, so axisSqueeze must not be set (AXIS_SCALE_WITH_SQUEEZE). Other families refuse it (AXIS_SCALE_UNSUPPORTED_FAMILY). Write the real tick values in axisTickValues and the axis names in axisTitles. The observer recomputes y/x itself: AXIS_SCALE_RATIO_MISMATCH means the recorded axisRatio differs from it, EQUAL_UNIT_SCALE_MISMATCH that the drawn figure does not follow it.'],
  [/OVERLAY_NAME_|OVERLAY_LABEL_INVALID/,'graphPlan.overlays.names:[{id,text,segment|line|curveX,labelDirection?}] writes a plain name (Korean, letters, digits, spaces, brackets; 1 to 10 characters, no leading or trailing space) beside an overlay segment (segment: its id), an overlay line (line: its id) or the drawn curve (curveX: an x inside the source domain), at most 4 per figure, exactly one place per entry. The equation label of an overlay line (label) takes only ASCII math and refuses Hangul with OVERLAY_LABEL_INVALID: write names in names instead. OVERLAY_NAME_LABEL_* codes come from the observer reading the final SVG: the text must be the plain text label, a segment or line name belongs to that segment or line (nearest, or a leader starting on it), a curve name stands near its curveX point and nearer the curve than any overlay segment or line.'],
  [/COMPOSITE_CAPTION_TOO_LARGE/,'A panel caption of plain text wider than its cell is broken into two lines at a space automatically, and a caption taller than the standard row makes the caption rows taller; the code remains only when a caption still does not fit (a formula in it, no space to break at, or a line still wider than the cell): shorten the caption text (24 characters at most) or widen the cell.'],
  [/NUMBER_LINE_(HIDE_SET_LABEL_INVALID|VALUE_SIDE_INVALID|SPANS_INVALID|SPAN_POINT_UNKNOWN|SPAN_LABEL_INVALID|SPAN_TOO_SHORT)/,'number-line-figure-v1 (E34): rows[].hideSetLabel:true (SET/RESULT) leaves out the inequality written over the row; parameter.hideNote:true leaves out the "a=... 일 때의 그림" note (a fraction value in the note is written small, on one line); a POINTS point may carry name "뉴욕" (a Hangul word of 2 to 5 syllables, plain text) and valueSide "ABOVE"|"BELOW" (default BELOW); a POINTS row may carry spans:[{from,to,label?,style?,side?}] (at most 3; from/to are ids of the row, style BRACE (default, under the labels) | ARROW (from to to, above the names) | DOUBLE_ARROW, side ABOVE|BELOW, label a Korean phrase of at most 9 characters or a short formula, never the answer). NUMBER_LINE_SPAN_TOO_SHORT: the two points are closer than 24 px: widen the range or drop the span.'],
  [/STAT_CLASS_SUM_(INVALID|OVERLAP)|STAT_UNKNOWN_LABEL_INVALID/,'stat-chart-figure-v1 (E34) classSums: [{series?,from,to,label?,unit?}] or, for classes that do not touch (both sides of a torn class), [{classes:[[0,2],[4,5]] | [0,1,2,4,5],label?}] (ascending class numbers, no from/to with it, no class in two brackets of one series; the label of a number must be the exact sum). unknownLabels[].relHeight (0.05..20: a number, "3/2" or "0.5") makes the dotted outlines stand in that ratio (2x with relHeight 2, x with 1); without it all are equally high.'],
  [/STAT_TITLE_INVALID/,'stat-chart-figure-v1 frequency charts (E34): xTitle/yTitle are one line up to 14 characters, or 15 to 28 characters with a single space to break at into two lines of at most 14 each (no leading, trailing or double space); the legend (series names, 14 characters) and the x title widen the frame by themselves. Other chart kinds keep 14 characters.'],
  [/STAT_DOT_(PLOT_INVALID|VALUE_INVALID|STACK_TOO_TALL|BREAK_INVALID|STEP_INVALID|PLOT_TOO_DENSE)/,'stat-chart-figure-v1 DOT_PLOT (E34): chart {kind:"DOT_PLOT",values:[whole numbers 0..9999, at most 60] | counts:[{value,count<=12}],step?,axisBreak?:{from,to},xTitle?}: one dot per datum stacked over its value (a stack of at most 12). step (whole number, default chosen by the engine) is the label step; with step>1 every integer between has a short tick. axisBreak cuts the line for an outlier: all data are <= from or >= to, none between, to-from>=2. TOO_DENSE: the numbers or the unit would not fit: give a bigger step or an axisBreak.'],
  [/STAT_DICE_GROUP_(INVALID|OVERLAP|EMPTY)|STAT_TREE_HIGHLIGHT_INVALID/,'stat-chart-figure-v1 (E34) DICE_TABLE highlightGroups:[{highlight:<condition>|cells:[[col,row]...],tone:1|2}] (1 to 4 groups, no cell in two groups, none empty, not together with highlight); colVar/rowVar: one lowercase letter, null (nothing written) or a Hangul phrase of at most 8 characters (written over the columns / left of the rows; conditions then call the variable a / b). TREE highlightPaths:[["승","패","승"]] names the labels from the root\'s child down to a leaf (labels among siblings must differ): those branches are heavy, the leaf ringed. pathColumn:true puts the path probabilities in one column right of every leaf (needs showPathProbability): use it when STAT_LABELS_TOO_CLOSE says a path probability meets a deeper branch.'],
];
export const hintFor=text=>HINTS.filter(([re])=>re.test(text)).map(([,h])=>h);
